document.querySelectorAll(".post-content pre").forEach(e=>{const t=document.createElement("button");t.type="button",t.className="copy-code",t.textContent="Copy",t.addEventListener("click",async()=>{const n=e.querySelector("code")||e;try{await navigator.clipboard.writeText(n.innerText.replace(/\n$/,"")),t.textContent="Copied"}catch{t.textContent="Failed"}setTimeout(()=>t.textContent="Copy",1500)});const n=document.createElement("div");n.className="code-block",e.replaceWith(n),n.append(e,t)})